package com.sigtm.backend.service;
import com.sigtm.backend.exception.ResourceNotFoundException; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class IncidenciaProveedorService {private final IncidenciaProveedorRepository incidents;private final ProveedorRepository suppliers;private final OrdenCompraRepository orders;private final AuditoriaService audit;
 @Transactional public IncidenciaProveedor crear(Long supplierId,Long orderId,IncidenciaProveedor data){Proveedor s=suppliers.findById(supplierId).orElseThrow(()->new ResourceNotFoundException("Proveedor no encontrado"));if(!Set.of("CALIDAD","ENTREGA","FACTURACION","DOCUMENTACION").contains(data.getCategory()))throw new IllegalArgumentException("Categoría inválida");if(!Set.of("BAJA","MEDIA","ALTA","CRITICA").contains(data.getPriority()))throw new IllegalArgumentException("Prioridad inválida");data.setSupplier(s);data.setPurchaseOrder(orderId==null?null:orders.findDetailedById(orderId).orElseThrow(()->new ResourceNotFoundException("Orden no encontrada")));data.setStatus("ABIERTA");data.setReportedAt(LocalDateTime.now());IncidenciaProveedor saved=incidents.save(data);audit.registrar("CREATE","INCIDENCIA_PROVEEDOR",saved.getId(),"Incidencia "+saved.getCategory());return saved;}
 @Transactional public IncidenciaProveedor resolver(Long id,String resolution){IncidenciaProveedor i=incidents.findById(id).orElseThrow(()->new ResourceNotFoundException("Incidencia no encontrada"));if(!"ABIERTA".equals(i.getStatus()))throw new IllegalArgumentException("La incidencia ya fue cerrada");i.setStatus("RESUELTA");i.setResolvedAt(LocalDateTime.now());i.setResolution(resolution);audit.registrar("UPDATE","INCIDENCIA_PROVEEDOR",id,"Incidencia resuelta");return incidents.save(i);}
 @Transactional(readOnly=true) public List<IncidenciaProveedor> abiertas(){return incidents.findByStatusOrderByPriorityDescReportedAtAsc("ABIERTA");}}
